import {estimateProductionCost} from './production-cost-core.js?v=2.17.3';
import {analyzeImageForProduction} from './production-cost-analysis.js?v=2.17.3';
import {nestItems} from './nesting-core.js?v=2.17.3';
import {createUserRipSettings,validateRipSettings,ripInkFactors} from './rip-calibration.js?v=2.17.3';

const h=(value='')=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const channels=['C','M','Y','K','W'],channelLabels={C:'Ciano',M:'Magenta',Y:'Amarelo',K:'Preto',W:'Branco'},baseUnit={film:'m',powder:'g',ink:'ml'};
const number=value=>String(value??'').trim()===''?null:Number(String(value).replace(',','.'));
const fmt=(value,digits=2)=>Number.isFinite(Number(value))&&value!==null&&value!==undefined?Number(value).toLocaleString('pt-BR',{maximumFractionDigits:digits}):'—';
const inputValue=value=>value===null||value===undefined?'':String(value).replace('.',',');
const money=value=>value===null||value===undefined||!Number.isFinite(Number(value))?'Não calculado':Number(value).toLocaleString('pt-BR',{style:'currency',currency:'BRL',minimumFractionDigits:2,maximumFractionDigits:Number(value)!==0&&Math.abs(Number(value))<.01?4:2});
const clone=value=>structuredClone(value),id=()=>crypto.randomUUID();
const kindLabel=kind=>({film:'Filme',powder:'Pó TPU',ink:'Tinta'}[kind]||kind);
const duration=minutes=>Number.isFinite(minutes)?minutes>=60?`${Math.floor(minutes/60)} h ${fmt(minutes%60,0)} min`:`${fmt(minutes,1)} min`:'Não calibrado';
const purchaseUnitPrice=purchase=>purchase.totalPrice!==null&&purchase.totalPrice!==undefined&&Number.isFinite(purchase.totalPrice)&&purchase.quantity>0?purchase.totalPrice/purchase.quantity:null;
const imageURL=value=>typeof value==='string'&&/^(?:blob:|https?:\/\/|data:image\/(?:png|jpeg|webp);base64,)/i.test(value)?value:'';

export function costLayoutPreviewHTML(layout,items){
  const width=Number(layout?.filmWidthMm),length=Number(layout?.lengthMm);
  if(!(width>0&&length>0))return '';
  const sources=new Map(items.map(item=>[String(item.localId||item.id),item])),pattern=`cost-checker-${id()}`;
  const placements=(layout.placements||[]).map(placement=>{
    const item=sources.get(String(placement.id)),url=imageURL(item?.url||item?.previewUrl||item?.previewDataUrl),sourceWidth=Number(placement.sourceWidthMm||item?.widthCm*10),sourceHeight=Number(placement.sourceHeightMm||item?.heightCm*10),rotation=Number(placement.rotation||0),x=Number(placement.xMm),y=Number(placement.yMm),w=Number(placement.widthMm),height=Number(placement.heightMm);
    if(![sourceWidth,sourceHeight,rotation,x,y,w,height].every(Number.isFinite)||sourceWidth<=0||sourceHeight<=0||w<=0||height<=0)return '';
    const label=`${item?.label||placement.label||'Arte'} · cópia ${Number(placement.copy??0)+1} · ${fmt(sourceWidth/10)} × ${fmt(sourceHeight/10)} cm · ${rotation}°`;
    return `<g data-cost-preview-art="${h(placement.id)}"><title>${h(label)}</title><rect x="${x}" y="${y}" width="${w}" height="${height}" fill="none" stroke="#ff8b49" stroke-opacity=".55" stroke-width=".65" vector-effect="non-scaling-stroke"/>${url?`<image href="${h(url)}" x="${-sourceWidth/2}" y="${-sourceHeight/2}" width="${sourceWidth}" height="${sourceHeight}" transform="translate(${x+w/2} ${y+height/2}) rotate(${rotation})" preserveAspectRatio="none"/>`:`<text x="${x+w/2}" y="${y+height/2}" text-anchor="middle" font-size="5" fill="#fff">Prévia indisponível</text>`}</g>`;
  }).join('');
  return `<div class="cost-layout-scroll"><svg class="cost-layout-real" viewBox="0 0 ${width} ${length}" width="${width}" height="${length}" role="img" aria-label="Encaixe proporcional com as imagens reais das artes; ${layout.placements?.length||0} aplicações"><defs><pattern id="${pattern}" width="12" height="12" patternUnits="userSpaceOnUse"><rect width="12" height="12" fill="#292a30"/><path d="M0 0h6v6H0zM6 6h6v6H6z" fill="#3b3c43"/></pattern></defs><rect width="${width}" height="${length}" fill="url(#${pattern})"/>${placements}</svg></div>`;
}

export function costPerArtHTML(estimate,items=[],imageUrls={}){
  if(!Array.isArray(estimate.perArt)||!estimate.perArt.length)return '';
  const sources=new Map(items.map(item=>[String(item.localId||item.id),item]));
  return `<section class="cost-per-art"><h3>Consumo por arte</h3><p>Quantidades abaixo incluem todas as cópias de cada arte. Tintas e pó são específicos da estampa; filme, preparação, operação e comissões permanecem no total do trabalho, sem rateio inventado.</p>${estimate.perArt.map(art=>{const item=sources.get(String(art.id||art.localId))||{},url=imageURL(imageUrls[art.id||art.localId]||item.url||item.previewUrl||item.previewDataUrl),rows=art.rows||[];return `<details class="cost-per-art-card" data-cost-art="${h(art.id||art.localId)}"><summary>${url?`<img src="${h(url)}" alt="${h(art.label||item.label||'Arte')}" loading="lazy">`:'<span class="cost-art-no-preview">Sem prévia</span>'}<span><b>${h(art.label||item.label||'Arte')}</b><small>${fmt(art.widthCm)} × ${fmt(art.heightCm)} cm · ${fmt(art.quantity,0)} ${art.quantity===1?'aplicação':'aplicações'}</small><small>${fmt(art.printedAreaM2,4)} m² impressos · tinta + pó</small></span><strong>${money(art.complete?art.consumablesCost??art.knownConsumablesCost:art.knownConsumablesCost)}<small>${art.complete?'Subtotal estimado':'Subtotal parcial'}</small></strong></summary><div class="cost-art-channel-list">${rows.map(row=>`<div data-cost-art-channel="${h(row.channel||row.key)}"><b>${h(row.label||channelLabels[row.channel]||row.key)}</b><span>${fmt(row.quantity,4)} ${h(row.unit||'')}</span><strong>${money(row.cost)}</strong></div>`).join('')}</div>${art.warnings?.length?`<ul class="cost-art-warnings">${art.warnings.map(warning=>`<li>${h(warning)}</li>`).join('')}</ul>`:''}</details>`}).join('')}<p class="cost-small-note">${estimate.channelMode==='CMYKW'?'Perfil CMYKW: Ciano, Magenta, Amarelo, Preto e Branco são canais físicos separados.':'Perfil CMYW: preto na imagem é formado por Ciano + Magenta + Amarelo; não existe consumo de cartucho K neste perfil.'} A separação é uma aproximação por pixels, não um relatório ICC do RIP.</p></section>`;
}

export function createExampleCostProfile(name='Perfil inicial — calibrar'){
  return {id:id(),name,channelMode:'CMYW',film30PurchaseId:null,film60PurchaseId:null,powderPurchaseId:null,inkPurchaseIds:{C:null,M:null,Y:null,K:null,W:null},calibration:{inkMlPerM2:{C:6.6667,M:6.6667,Y:6.6667,W:37.142857,K:null},powderGPerM2:8,inkWastePercent:0,filmWastePercent:0,leaderCm:0,time60MinPerM:52,time30MinPerM:null,time30Mode:'measured',setupMinutes:0,curingMinutes:0,laborPerHour:0,kwhPerHour:0,kwhPrice:0,maintenancePerM:0,ripPerM:0}};
}
export function createDefaultCostState(){const profile=createExampleCostProfile();return {version:1,activeProfileId:profile.id,purchases:[],profiles:[profile]};}
export function applyUserRipPreset(profile){return {...clone(profile),channelMode:'CMYW',rip:createUserRipSettings()};}
export function profileWithRipMode(profile,mode){if(!profile.rip||!['normal','white-extra'].includes(mode))return profile;return {...profile,rip:{...profile.rip,mode}};}
export function ripWithCurrentReference(rip){const next=validateRipSettings(rip);next.referenceOutputPercent={...next.outputPercent};next.referenceLayers={...next.layers,W:next.layers.W+(next.mode==='white-extra'?next.extraWhiteLayers:0)};return validateRipSettings(next);}
export function normalizeCostState(input){
  const state=clone(input);for(const profile of state.profiles||[]){profile.inkPurchaseIds={C:null,M:null,Y:null,K:null,W:null,...profile.inkPurchaseIds};profile.calibration={...profile.calibration,inkMlPerM2:{C:null,M:null,Y:null,K:null,W:null,...profile.calibration?.inkMlPerM2},time30Mode:profile.calibration?.time30Mode||'measured'};}if(!state.activeProfileId)state.activeProfileId=state.profiles?.[0]?.id||null;return state;
}
export function validateCostDraft(state){
  if(!state||state.version!==1||!Array.isArray(state.profiles)||!Array.isArray(state.purchases))throw new Error('Arquivo de custos incompatível. Use uma configuração exportada por este sistema.');
  if(!state.profiles.length)throw new Error('Mantenha pelo menos um perfil de produção.');
  const profileIds=new Set(),purchaseIds=new Set();
  for(const purchase of state.purchases){
    if(!purchase.id||purchaseIds.has(purchase.id))throw new Error('Identificadores de compras duplicados ou ausentes.');purchaseIds.add(purchase.id);
    if(!String(purchase.name||'').trim()||!baseUnit[purchase.kind]||purchase.unit!==baseUnit[purchase.kind])throw new Error('Revise o nome, tipo e unidade de cada compra.');
    if(!(Number.isFinite(purchase.quantity)&&purchase.quantity>0)||(purchase.totalPrice!==null&&!(Number.isFinite(purchase.totalPrice)&&purchase.totalPrice>=0)))throw new Error(`Informe quantidade positiva e valor válido (ou vazio) para “${purchase.name}”.`);
    if(purchase.kind==='film'&&![30,60].includes(Number(purchase.widthCm)))throw new Error('Use largura nominal de 30 ou 60 cm na compra de filme.');
    if(purchase.kind==='ink'&&!channels.includes(purchase.channel))throw new Error('Selecione o canal da tinta.');
    if(purchase.kind==='powder'&&!['white','black'].includes(purchase.color))throw new Error('Selecione pó branco ou preto.');
  }
  const purchases=new Map(state.purchases.map(purchase=>[purchase.id,purchase]));
  for(const profile of state.profiles){
    if(!profile.id||profileIds.has(profile.id)||!String(profile.name||'').trim())throw new Error('Revise os nomes e identificadores dos perfis.');profileIds.add(profile.id);
    if(!['CMYW','CMYKW'].includes(profile.channelMode))throw new Error(`Selecione os canais do perfil “${profile.name}”.`);
    validateRipSettings(profile.rip);
    for(const [field,kind,width] of [['film30PurchaseId','film',30],['film60PurchaseId','film',60],['powderPurchaseId','powder',null]]){const key=profile[field];if(key){const purchase=purchases.get(key);if(!purchase||purchase.kind!==kind||(width&&Number(purchase.widthCm)!==width))throw new Error(`Compra incompatível no perfil “${profile.name}”.`);}}
    for(const channel of channels){const key=profile.inkPurchaseIds?.[channel];if(key){const purchase=purchases.get(key);if(!purchase||purchase.kind!=='ink'||purchase.channel!==channel)throw new Error(`Vincule uma compra da tinta ${channelLabels[channel]} ao canal ${channel}.`);}}
    const calibration=profile.calibration||{};if(!calibration.inkMlPerM2||typeof calibration.inkMlPerM2!=='object'||Array.isArray(calibration.inkMlPerM2))throw new Error('Revise a calibração de tintas do perfil.');for(const [key,value] of Object.entries(calibration)){if(key==='inkMlPerM2'||key==='time30Mode')continue;if(value!==null&&(!Number.isFinite(value)||value<0))throw new Error(`Valor inválido de ${key} em “${profile.name}”.`);}
    if(!['proportional','measured'].includes(calibration.time30Mode))throw new Error('Selecione como estimar o tempo do filme de 30 cm.');
    for(const channel of channels){const value=calibration.inkMlPerM2?.[channel];if(value!==null&&value!==undefined&&(!Number.isFinite(value)||value<0))throw new Error(`Consumo inválido da tinta ${channelLabels[channel]}.`);}
  }
  if(!profileIds.has(state.activeProfileId))throw new Error('Selecione um perfil padrão válido.');return state;
}
export function purchaseReferences(state,purchaseId){return state.profiles.filter(profile=>[profile.film30PurchaseId,profile.film60PurchaseId,profile.powderPurchaseId,...Object.values(profile.inkPurchaseIds||{})].includes(purchaseId));}
export function projectCommissionState(commission,isAdmin){
  const ids=[...new Set((commission?.projectIds||[]).filter(value=>typeof value==='string'&&value))].sort(),known=typeof commission?.projectTotal==='number'&&Number.isFinite(commission.projectTotal)&&commission.projectTotal>=0,complete=commission?.complete===true,enabled=commission?.enabled===true;
  const state=!complete?'unknown':!enabled?'disabled':!ids.length?'unlinked':!known?'unknown':'available';
  return {state,projectIds:ids,amount:known?commission.projectTotal:null,canInclude:Boolean(isAdmin&&state==='available'),key:JSON.stringify([ids,known?commission.projectTotal:null,complete,enabled]),label:state==='unknown'?(known?'Comissões parcialmente visíveis':'Comissões indisponíveis'):state==='disabled'?'Comissões desativadas na conta':state==='unlinked'?'Nenhum projeto vinculado':'Comissões dos projetos inteiros'};
}
export function costCloudAvailability(snapshot,{admin=true}={}){
  const unavailable=snapshot?.cloudAvailable===false,missing=['42P01','PGRST205'].includes(snapshot?.errorCode),permission=['42501','COST_PERMISSION'].includes(snapshot?.errorCode);
  const explanation=missing?'Cadastro na nuvem ainda não habilitado.':permission?'Sem permissão para salvar a configuração de custos na nuvem.':'Não foi possível confirmar o acesso ao cadastro de custos na nuvem.';
  const legacy=snapshot?.mode==='local-draft';
  return {enabled:admin&&!unavailable&&!legacy,reason:!admin?(unavailable?`${explanation} Peça ao titular da conta para conferir. Nenhum cadastro novo é salvo apenas neste aparelho.`:'Somente o titular da conta pode salvar custos.'):unavailable?`${explanation} ${snapshot?.hasLocalDraft?'Os cadastros antigos deste aparelho estão preservados. Exporte uma cópia de segurança.':'Nenhum novo cadastro foi salvo somente neste aparelho.'} Use “Recarregar versão da conta” para tentar novamente. Novos cadastros só são salvos na nuvem.`:legacy?'Sincronize os cadastros antigos deste aparelho antes de editá-los na nuvem.':''};
}

export function createProductionCostUI(ctx){
  let cached=null,disposed=false;const analysisCache=new Map(),listeners=new Set(),modalClosers=new Set(),panelDisposers=new Set(),downloadUrls=new Map();
  const destroy=()=>{if(disposed)return;disposed=true;globalThis.window?.removeEventListener('z19:account-changing',destroy);for(const close of [...modalClosers].reverse())close(true);for(const dispose of [...panelDisposers])dispose();for(const [url,timer] of downloadUrls){clearTimeout(timer);URL.revokeObjectURL(url)}downloadUrls.clear();analysisCache.clear();listeners.clear();cached=null;};
  globalThis.window?.addEventListener('z19:account-changing',destroy);
  const canView=()=>{try{return ctx.canView===undefined?true:(typeof ctx.canView==='function'?ctx.canView():ctx.canView)===true}catch{return false}};
  const assertOpen=()=>{if(!canView()){destroy();const error=new Error('Área privada de custos.');error.code='COST_PRIVATE';throw error}if(disposed)throw new DOMException('A conta mudou. Reabra o painel de custos.','AbortError')};
  const admin=()=>typeof ctx.isAdmin==='function'?ctx.isAdmin():Boolean(ctx.isAdmin),toast=(message,type='ok')=>{if(!disposed&&canView())ctx.toast?.(message,type)};
  const stateForUI=input=>{const data=input?.version===1?normalizeCostState(input):createDefaultCostState();if(!data.profiles.length){const profile=createExampleCostProfile();data.profiles.push(profile);data.activeProfileId=profile.id}return data};
  async function load(force=false){
    assertOpen();
    if(cached&&!force)return cached;
    if(!ctx.costStore){cached={data:createDefaultCostState(),mode:'unavailable',cloudAvailable:false,errorCode:'COST_STORE_UNAVAILABLE',warning:'O cadastro na nuvem está indisponível. Não serão criados novos cadastros apenas neste aparelho.'};return cached;}
    const result=await ctx.costStore.load();assertOpen();const data=stateForUI(result?.data);
    cached={...result,data,mode:result.mode||'unavailable',warning:result.warning||(!result?.data?.profiles?.length?'Perfil com calibração inicial de exemplo. Cadastre suas compras, ajuste ao equipamento e salve na nuvem.':'')};return cached;
  }
  const selectedProfile=(state,profileId)=>state.profiles.find(profile=>profile.id===profileId)||state.profiles.find(profile=>profile.id===state.activeProfileId)||state.profiles[0];
  const modeHTML=snapshot=>`<div class="cost-storage-note ${snapshot.mode==='cloud'?'cloud':'draft'}"><b>${snapshot.mode==='cloud'?'Configuração na nuvem':snapshot.mode==='local-draft'?'Cadastros antigos preservados':'Nuvem indisponível'}</b>${snapshot.warning?`<span>${h(snapshot.warning)}</span>`:''}</div>`;
  const shell=(title,eyebrow='Produção DTF')=>{
    assertOpen();
    const modal=document.createElement('div'),focus=document.activeElement,oldOverflow=document.body.style.overflow,titleId=`cost-title-${id()}`;modal.className='modal-backdrop production-cost-backdrop';modal.innerHTML=`<div class="modal production-cost-modal" role="dialog" aria-modal="true" aria-labelledby="${titleId}"><div class="modal-head"><div><div class="eyebrow">${h(eyebrow)}</div><h2 id="${titleId}">${h(title)}</h2></div><button class="btn ghost small" data-cost-close aria-label="Fechar">×</button></div><div data-cost-content></div></div>`;
    let closed=false;const cleanups=[];const close=(force=false)=>{if(closed)return;closed=true;modalClosers.delete(close);cleanups.forEach(fn=>fn());modal.remove();document.body.style.overflow=force?'':oldOverflow;if(!force&&focus?.isConnected)focus.focus();};modalClosers.add(close);
    const blockPrivateEvent=event=>{if(disposed||!canView()){event.preventDefault();event.stopImmediatePropagation();destroy()}};for(const type of ['click','input','change'])modal.addEventListener(type,blockPrivateEvent,true);
    modal.querySelector('[data-cost-close]').onclick=()=>close();modal.onkeydown=event=>{if(event.key==='Escape'){event.preventDefault();close()}else if(event.key==='Tab'){const nodes=[...modal.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),summary,a[href]')].filter(node=>node.getClientRects().length),first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}};document.body.style.overflow='hidden';document.body.appendChild(modal);modal.querySelector('[data-cost-close]').focus();return {modal,body:modal.querySelector('[data-cost-content]'),close,cleanups,isClosed:()=>closed};
  };
  const downloadJSON=state=>{assertOpen();const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`custos-dtf-${new Date().toISOString().slice(0,10)}.json`;link.click();downloadUrls.set(url,setTimeout(()=>{URL.revokeObjectURL(url);downloadUrls.delete(url)},60000));};
  async function openSettings(){
    const view=shell('Insumos e perfis de custo','Configurações de produção');view.body.innerHTML='<div class="empty"><span class="loading"></span> Carregando configuração…</div>';
    let snapshot;try{snapshot=await load(true)}catch(error){if(disposed||!canView()){destroy();return}view.body.innerHTML=`<div class="cost-inline-error">${h(error.message)} Nenhum cadastro novo foi salvo apenas neste aparelho.</div><button class="btn" data-cost-retry>Tentar consultar a nuvem novamente</button>`;view.body.querySelector('[data-cost-retry]').onclick=()=>{assertOpen();view.close();openSettings()};return;}
    if(view.isClosed())return;editSettings(view,snapshot);
  }
  function editSettings(view,snapshot){
    let draft=normalizeCostState(snapshot.data),profileId=draft.activeProfileId,tab='profiles',editingPurchase=null,armedDelete=null,reloadArmed=false,ripPresetArmed=null,ripReferenceArmed=null,busy=false,migrationPlan=null,migrationMessage='';const readonly=!admin();
    const legacyHTML=()=>snapshot.hasLocalDraft?`<section class="cost-legacy-sync" aria-label="Sincronizar cadastros antigos"><h3>Seus cadastros deste aparelho estão preservados</h3><p>${snapshot.localDraftData?.purchases?.length||0} compras e ${snapshot.localDraftData?.profiles?.length||0} perfis encontrados. A sincronização não substitui cadastros que já estão na nuvem. A cópia antiga só será removida depois de a nuvem confirmar todos os dados.</p><div class="cost-sync-actions"><button class="btn" data-export-legacy ${busy?'disabled':''}>Exportar cópia deste aparelho</button><button class="btn primary" data-prepare-legacy ${busy||readonly||snapshot.cloudAvailable===false||!ctx.costStore?.prepareLocalDraftSync?'disabled':''}>Sincronizar cadastros deste aparelho</button></div>${migrationPlan?migrationPlan.canSync?`<div class="cost-sync-review"><b>Confira antes de enviar</b><p>${migrationPlan.summary.addedPurchases} compras e ${migrationPlan.summary.addedProfiles} perfis serão acrescentados. ${migrationPlan.summary.copiedPurchases+ migrationPlan.summary.copiedProfiles?`${migrationPlan.summary.copiedPurchases} compras e ${migrationPlan.summary.copiedProfiles} perfis conflitantes serão preservados em cópias identificadas “deste aparelho”.`:''} O perfil padrão da nuvem será mantido, quando já existir.</p><button class="btn primary" data-confirm-legacy ${busy?'disabled':''}>Confirmar envio para a nuvem</button></div>`:`<div class="cost-sync-conflicts"><b>Há versões diferentes dos mesmos cadastros</b><ul>${migrationPlan.conflicts.map(conflict=>`<li>${h(conflict.kind==='purchase'?'Compra':conflict.kind==='profile'?'Perfil':'Configuração')}: ${h(conflict.name)}</li>`).join('')}</ul><p>Nada foi sobrescrito. Você pode manter as duas versões, criando cópias com vínculos de compras corrigidos, ou exportar a cópia antiga para revisar.</p><button class="btn" data-copy-legacy ${busy||migrationPlan.conflicts.some(conflict=>conflict.kind==='setting')?'disabled':''}>Preservar as duas versões em cópias separadas</button></div>`:''}${migrationMessage?`<p class="cost-inline-error" role="status">${h(migrationMessage)}</p>`:''}</section>`:'';
    const synchronize=async(stage,preserveBoth=false)=>{
      if(busy||disposed||!canView())return;
      if(editingPurchase||JSON.stringify(draft)!==JSON.stringify(normalizeCostState(snapshot.data))){migrationMessage='Há alterações nesta tela ainda não salvas. Salve-as na nuvem ou exporte e recarregue a versão da conta antes de sincronizar a cópia antiga.';render();return}
      busy=true;migrationMessage='';render();
      try{assertOpen();if(stage==='prepare'){migrationPlan=await ctx.costStore.prepareLocalDraftSync({preserveBoth});assertOpen()}else{const result=await ctx.costStore.syncLocalDraft({token:migrationPlan?.token});assertOpen();if(result.mode!=='cloud'||result.cloudAvailable===false)throw new Error('A nuvem não confirmou a sincronização. Os cadastros deste aparelho foram preservados.');cached={...result,data:stateForUI(result.data)};snapshot=cached;draft=clone(cached.data);profileId=draft.activeProfileId;migrationPlan=null;listeners.forEach(listener=>listener());toast('Cadastros sincronizados e confirmados na nuvem.');}
      }catch(error){if(disposed||!canView()){destroy();return}migrationPlan=null;migrationMessage=error.message||String(error)}finally{busy=false;if(!disposed&&!view.isClosed())render()}
    };
    const bindings=(profile)=>[
      ['Consumo de pó TPU','powderGPerM2','g / m²'],['Perda de tinta','inkWastePercent','%'],['Perda de filme','filmWastePercent','%'],['Avanço inicial / final de filme','leaderCm','cm'],
      ['Tempo de impressão · filme 60 cm','time60MinPerM','min / metro'],['Tempo medido · filme 30 cm','time30MinPerM','min / metro'],['Preparação por trabalho','setupMinutes','min'],['Cura por trabalho','curingMinutes','min'],
      ['Mão de obra','laborPerHour','R$ / hora'],['Consumo de energia','kwhPerHour','kWh / hora'],['Preço da energia','kwhPrice','R$ / kWh'],['Manutenção','maintenancePerM','R$ / metro'],['RIP / software','ripPerM','R$ / metro']
    ];
    const purchaseOption=(value,filter)=>`<option value="">Não informado</option>${draft.purchases.filter(filter).map(purchase=>`<option value="${h(purchase.id)}" ${purchase.id===value?'selected':''}>${h(purchase.name)} · ${money(purchaseUnitPrice(purchase))}/${h(purchase.unit)}</option>`).join('')}`;
    const drawProfile=()=>{
      const profile=selectedProfile(draft,profileId);profileId=profile.id;const calibration=profile.calibration;
      return `<div class="cost-profile-toolbar"><label>Perfil para editar<select data-edit-profile>${draft.profiles.map(item=>`<option value="${h(item.id)}" ${item.id===profile.id?'selected':''}>${h(item.name)}${item.id===draft.activeProfileId?' · padrão':''}</option>`).join('')}</select></label><button class="btn small" data-new-profile>Novo perfil</button><button class="btn small" data-clone-profile>Duplicar</button></div><div class="cost-grid two"><label>Nome do perfil<input data-profile-name value="${h(profile.name)}"></label><label>Canais da impressora<select data-channel-mode><option value="CMYW" ${profile.channelMode==='CMYW'?'selected':''}>CMY + branco · sem canal K</option><option value="CMYKW" ${profile.channelMode==='CMYKW'?'selected':''}>CMYK + branco</option></select></label></div><div class="cost-profile-actions"><button class="btn small ${draft.activeProfileId===profile.id?'primary':''}" data-set-default>${draft.activeProfileId===profile.id?'Perfil padrão ativo':'Usar como padrão'}</button><button class="btn ghost small" data-delete-profile ${draft.profiles.length<2?'disabled':''}>${armedDelete===profile.id?'Confirmar exclusão deste perfil':'Excluir perfil'}</button></div><div class="cost-example-note"><b>Calibração inicial de exemplo</b><span>Os consumos e tempos iniciais são referências editáveis. Meça sua produção e substitua pelos valores reais. Preços de compras começam vazios.</span></div><h3>Compras usadas neste perfil</h3><div class="cost-grid two"><label>Filme 30 cm · impressão útil 28 cm<select data-profile-purchase="film30PurchaseId">${purchaseOption(profile.film30PurchaseId,p=>p.kind==='film'&&Number(p.widthCm)===30)}</select></label><label>Filme 60 cm · impressão útil 58 cm<select data-profile-purchase="film60PurchaseId">${purchaseOption(profile.film60PurchaseId,p=>p.kind==='film'&&Number(p.widthCm)===60)}</select></label><label>Pó TPU<select data-profile-purchase="powderPurchaseId">${purchaseOption(profile.powderPurchaseId,p=>p.kind==='powder')}</select></label></div><div class="cost-ink-grid">${channels.filter(channel=>channel!=='K'||profile.channelMode==='CMYKW').map(channel=>`<div class="cost-channel-card" data-channel="${channel}"><b><i></i>${channelLabels[channel]} · ${channel}</b><label>Compra da tinta<select data-ink-purchase="${channel}">${purchaseOption(profile.inkPurchaseIds?.[channel],p=>p.kind==='ink'&&p.channel===channel)}</select></label><label>Consumo a 100% de cobertura<input data-ink-calibration="${channel}" inputmode="decimal" value="${inputValue(calibration.inkMlPerM2?.[channel])}" placeholder="Não calibrado"><small>ml / m²</small></label></div>`).join('')}</div><h3>Consumos, perdas e operação</h3><div class="cost-grid three">${bindings(profile).map(([label,key,unit])=>`<label>${label}<span class="cost-input-unit"><input data-calibration="${key}" inputmode="decimal" value="${inputValue(calibration[key])}" placeholder="Não informado"><small>${unit}</small></span></label>`).join('')}<label>Tempo no filme de 30 cm<select data-time30-mode><option value="proportional" ${calibration.time30Mode==='proportional'?'selected':''}>Estimar proporcional ao de 60 cm</option><option value="measured" ${calibration.time30Mode==='measured'?'selected':''}>Usar tempo medido de 30 cm</option></select></label></div><p class="cost-small-note">Campo vazio significa desconhecido. Zero significa custo ou tempo não incluído. O tempo proporcional é uma estimativa, não uma medição da máquina.</p>`;
    };
    const drawRip=profile=>{
      const rip=profile.rip,header=`<div class="cost-section-head"><div><h3>Configuração RIP</h3><p>Limites de tinta e camadas, separados do preço dos insumos.</p></div><button class="btn small" data-rip-preset>${ripPresetArmed===profile.id?'Confirmar substituição pelo RIP dos prints':'Usar configuração dos prints (CMYW)'}</button></div>`;
      if(!rip)return `<section class="cost-rip-settings">${header}<p>Este perfil usa a calibração existente, sem ajustes de RIP. Aplicar os prints é uma escolha explícita: preserva suas compras, preços e consumos em ml/m², que passam a representar o modo normal de referência dos prints.</p></section>`;
      const reference=channels.map(channel=>`${channel}: ${fmt(rip.referenceOutputPercent?.[channel])}% / ${fmt(rip.referenceLayers?.[channel],0)} cam.`).join(' · ');
      return `<section class="cost-rip-settings">${header}<div class="cost-grid three"><label>Modo padrão deste perfil<select data-rip-field="mode"><option value="normal" ${rip.mode==='normal'?'selected':''}>Normal · ${rip.totalLayers} camadas</option><option value="white-extra" ${rip.mode==='white-extra'?'selected':''}>Branco reforçado · ${Number(rip.totalLayers)+Number(rip.extraWhiteLayers)} camadas</option></select></label><label>Resolução do RIP (DPI)<input data-rip-field="resolutionDpi" inputmode="numeric" value="${inputValue(rip.resolutionDpi)}"></label><label>Qualidade<select data-rip-field="quality"><option value="high" ${rip.quality==='high'?'selected':''}>Alta</option><option value="normal" ${rip.quality==='normal'?'selected':''}>Normal</option><option value="draft" ${rip.quality==='draft'?'selected':''}>Rascunho</option></select></label><label>Total de camadas normais<input data-rip-field="totalLayers" inputmode="numeric" value="${inputValue(rip.totalLayers)}"></label><label>Camadas adicionais de branco<input data-rip-field="extraWhiteLayers" inputmode="numeric" value="${inputValue(rip.extraWhiteLayers)}"></label><label>Modo de branco<input value="Branco de substrato / base" readonly></label></div><div class="cost-rip-channels">${channels.map(channel=>`<div class="cost-rip-channel"><b>${channelLabels[channel]} · ${channel}${channel==='K'&&profile.channelMode==='CMYW'?'<small>Canal K não usado no CMYW</small>':''}</b><label>Saída máxima (%)<input data-rip-percent="${channel}" inputmode="decimal" value="${inputValue(rip.outputPercent?.[channel])}" ${channel==='K'&&profile.channelMode==='CMYW'?'disabled':''}></label><label>Camadas normais<input data-rip-layers="${channel}" inputmode="numeric" value="${inputValue(rip.layers?.[channel])}" ${channel==='K'&&profile.channelMode==='CMYW'?'disabled':''}></label></div>`).join('')}</div><div class="cost-rip-reference"><b>Referência dos consumos em ml/m²</b><span>${h(reference)}</span><p>Os coeficientes de consumo acima são desta referência. A estimativa usa a razão entre saída × camadas atuais e de referência, sem contar essas camadas duas vezes. DPI não é convertido diretamente em ml.</p><button class="btn small" data-rip-reference>${ripReferenceArmed===profile.id?'Confirmar: medi o consumo com esta configuração':'Definir configuração atual como nova referência'}</button><small>Use somente após medir o consumo nesta configuração e revisar os coeficientes em ml/m². Este botão não inventa nem altera uma medição.</small></div><div class="cost-grid three"><label>Tempo no branco reforçado<select data-rip-field="whiteExtraTimeMode"><option value="measured" ${rip.whiteExtraTimeMode==='measured'?'selected':''}>Usar medição própria (recomendado)</option><option value="proportional-layers" ${rip.whiteExtraTimeMode==='proportional-layers'?'selected':''}>Hipótese proporcional às camadas</option></select></label><label>Reforçado · filme 30 cm (min/m)<input data-rip-time="film30" inputmode="decimal" value="${inputValue(rip.whiteExtraMinutesPerM?.film30)}" placeholder="Ainda não medido"></label><label>Reforçado · filme 60 cm (min/m)<input data-rip-time="film60" inputmode="decimal" value="${inputValue(rip.whiteExtraMinutesPerM?.film60)}" placeholder="Ainda não medido"></label></div><div data-rip-preview class="cost-rip-preview"></div><p class="cost-small-note">O modo escolhido vale para todo o filme, inclusive trabalhos mistos. Não é aplicado automaticamente só às artes brancas. Filme e pó não recebem aumento automático pelo reforço de branco.</p></section>`;
    };
    const drawPurchaseForm=()=>{
      if(!editingPurchase)return '';const purchase=editingPurchase;
      return `<section class="cost-purchase-editor"><div class="cost-section-head"><h3>${draft.purchases.some(p=>p.id===purchase.id)?'Editar compra':'Nova compra'}</h3><button type="button" class="btn ghost small" data-cancel-purchase>Cancelar</button></div><div class="cost-grid two"><label>Nome / identificação<input data-purchase-field="name" value="${h(purchase.name)}" placeholder="Ex.: Rolo PET fornecedor A"></label><label>Insumo<select data-purchase-field="kind">${['film','powder','ink'].map(kind=>`<option value="${kind}" ${purchase.kind===kind?'selected':''}>${kindLabel(kind)}</option>`).join('')}</select></label>${purchase.kind==='film'?`<label>Largura do rolo<select data-purchase-field="widthCm"><option value="30" ${Number(purchase.widthCm)===30?'selected':''}>30 cm</option><option value="60" ${Number(purchase.widthCm)===60?'selected':''}>60 cm</option></select></label>`:purchase.kind==='powder'?`<label>Tipo de pó<select data-purchase-field="color"><option value="white" ${purchase.color==='white'?'selected':''}>Branco</option><option value="black" ${purchase.color==='black'?'selected':''}>Preto</option></select></label>`:`<label>Canal da tinta<select data-purchase-field="channel">${channels.map(channel=>`<option value="${channel}" ${purchase.channel===channel?'selected':''}>${channelLabels[channel]} · ${channel}</option>`).join('')}</select></label>`}<label>Quantidade comprada (${baseUnit[purchase.kind]})<input data-purchase-field="quantity" inputmode="decimal" value="${inputValue(purchase.quantity)}" placeholder="Quantidade total do pacote"></label><label>Valor total pago (R$)<input data-purchase-field="totalPrice" inputmode="decimal" value="${inputValue(purchase.totalPrice)}" placeholder="Informe o valor da compra"></label><label>Data da compra<input data-purchase-field="purchasedAt" type="date" value="${h(purchase.purchasedAt||'')}"></label></div><div class="cost-purchase-shortcuts"><button class="btn small" data-quantity-shortcut="${purchase.kind==='film'?100:1000}">${purchase.kind==='film'?'Rolo de 100 metros':purchase.kind==='ink'?'1 litro = 1.000 ml':'1 kg = 1.000 g'}</button><b data-unit-price>${purchase.quantity>0&&purchase.totalPrice!==null?`${money(purchase.totalPrice/purchase.quantity)} / ${baseUnit[purchase.kind]}`:'Informe quantidade e valor para calcular o custo unitário'}</b></div><button class="btn primary" data-save-purchase>Adicionar à configuração</button></section>`;
    };
    const drawPurchases=()=>`<div class="cost-section-head"><div><h3>Compras de insumos</h3><p>Cadastre o que foi comprado, na unidade total do pacote.</p></div><button class="btn primary" data-new-purchase>＋ Compra</button></div>${drawPurchaseForm()}<div class="cost-purchase-list">${draft.purchases.length?draft.purchases.map(purchase=>{const refs=purchaseReferences(draft,purchase.id);return `<article><span class="cost-purchase-kind">${h(kindLabel(purchase.kind))}${purchase.kind==='film'?` ${purchase.widthCm} cm`:purchase.kind==='ink'?` · ${purchase.channel}`:` · ${purchase.color==='black'?'preto':'branco'}`}</span><div><b>${h(purchase.name)}</b><small>${fmt(purchase.quantity)} ${purchase.unit} por ${money(purchase.totalPrice)}${purchase.purchasedAt?` · ${h(purchase.purchasedAt.split('-').reverse().join('/'))}`:''}</small><strong>${money(purchaseUnitPrice(purchase))} / ${purchase.unit}</strong>${refs.length?`<small>Usada em: ${h(refs.map(profile=>profile.name).join(', '))}</small>`:''}</div><button class="btn small" data-edit-purchase="${h(purchase.id)}">Editar</button><button class="btn ghost small" data-delete-purchase="${h(purchase.id)}" ${refs.length?'disabled title="Troque esta compra nos perfis antes de removê-la"':''}>${armedDelete===purchase.id?'Confirmar remoção':'Remover'}</button></article>`}).join(''):'<div class="empty">Nenhuma compra cadastrada. Preços reais são necessários para calcular o custo.</div>'}</div>`;
    const render=()=>{
      assertOpen();if(view.isClosed())return;
      const editorReadonly=readonly||snapshot.cloudAvailable===false||snapshot.mode!=='cloud';
      view.body.innerHTML=`${modeHTML(snapshot)}${legacyHTML()}${readonly?'<p class="cost-inline-warning">Somente o titular da conta pode alterar compras e perfis.</p>':editorReadonly?'<p class="cost-inline-warning">Somente leitura. Os cadastros existentes estão protegidos; alterações são salvas exclusivamente na nuvem.</p>':'<p class="cost-small-note">Alterações desta tela só ficam cadastradas depois de “Salvar na nuvem”.</p>'}<div class="cost-tabs" role="tablist" aria-label="Configuração de custos"><button role="tab" aria-selected="${tab==='profiles'}" data-cost-tab="profiles">Perfis e calibração</button><button role="tab" aria-selected="${tab==='purchases'}" data-cost-tab="purchases">Compras (${draft.purchases.length})</button></div><fieldset class="cost-edit-fields" ${editorReadonly||busy?'disabled':''}>${tab==='profiles'?drawProfile():drawPurchases()}</fieldset><p class="cost-inline-error" data-settings-error role="alert"></p><div class="cost-settings-footer"><button class="btn" data-export-cost>Exportar JSON</button>${!readonly?`<button class="btn" data-import-cost ${editorReadonly||busy?'disabled':''}>Importar JSON</button><button class="btn primary" data-save-cloud>Salvar na nuvem</button>`:''}</div>`;
      view.body.querySelectorAll('[data-cost-tab]').forEach(button=>button.onclick=()=>{tab=button.dataset.costTab;armedDelete=null;render()});
      if(tab==='profiles')view.body.querySelector('.cost-edit-fields').insertAdjacentHTML('beforeend',drawRip(selectedProfile(draft,profileId)));
