  const temporaryRipHTML=(profile,override)=>profile.rip?`<div class="cost-rip-temporary"><label>Modo RIP desta estimativa<select data-temporary-rip><option value="" ${!override?'selected':''}>Usar modo do perfil (${profile.rip.mode==='white-extra'?'branco reforçado':'normal'})</option><option value="normal" ${override==='normal'?'selected':''}>Normal · ${fmt(profile.rip.totalLayers,0)} camadas</option><option value="white-extra" ${override==='white-extra'?'selected':''}>Branco reforçado · ${fmt(Number(profile.rip.totalLayers)+Number(profile.rip.extraWhiteLayers),0)} camadas</option></select></label><small>Escolha temporária, sem alterar o perfil salvo. Vale para o filme inteiro, inclusive artes coloridas; não apenas para artes brancas.</small></div>`:'';
